#!/bin/bash
S=/tmp/orig-srgn
D=/tmp/probe/work/failconds/walk2
L() { sed 's/^\[[^]]*Z /[/'; }
reset() { rm -rf "$D"; mkdir -p "$D"; cd "$D"; for i in 1 2 3 4 5 6; do printf 'hello world %d\n' $i > f$i.txt; done; }
t() { local n="$1"; shift; reset; echo "--- $n (interleaved stdout+stderr) ---"; timeout 20 "$S" "$@" </dev/null 2>&1 | grep -v Launching | L; echo "== files after =="; for f in *.txt; do printf '%s: %s\n' "$f" "$(cat "$f")"; done; }

t "M1 unsorted fail-any -vv" --stdout-detection force-pipe -G '*.txt' -u --fail-any -vv 'world'
t "M2 sorted fail-any -vv" --stdout-detection force-pipe -G '*.txt' --sorted -u --fail-any -vv 'world'
t "M3 unsorted --threads 1 fail-any -vv" --stdout-detection force-pipe -G '*.txt' --threads 1 -u --fail-any -vv 'world'
t "M4 unsorted fail-none nomatch -vv" --stdout-detection force-pipe -G '*.txt' -u --fail-none -vv 'ZZZ'
